  this.constructor(p);
}
dir$s14.prototype = new DirEvent();
dir$s14.prototype.afterInit = function(){
  var p = this._dir;document._dir = p;
   dir$s14HiddenColumnByTran(p);
}



dir$s14.prototype.beforeButtonDialogClick = function (id) {
  var p = this._dir;
  switch (id) {
    case 'ok':
		var d = p.valForm('ngay_hl'),d2 = p.valForm('ngay_hld');
		var k = $.date(d,"dd/mm/yy"),k2 = $.date(d2,"dd/mm/yy");
		if (p.valForm('ngay_hld') <= p.valForm('ngay_hl')) { 
			<!-- $.question('jkhj '+'Nhap sai ngay ??' ); -->
			<!-- $.showToast(p.msg('noDate')); -->

			$.alert(p.msg('noDate')+' ' + k + ' < ' + k2);			
			return false;
			Break;
			}	  		  
    default:
      break;
  }
  return true;
}
dir$s14.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
&VoucherExRateValid01;
    case 'ma_gd':
      dir$s14HiddenColumnByTran(p);
      break;
    case 'ma_ngv':

      break;
    case 'ty_gia':
      p.calcExpressionAll(0, '!ty_gia');
      break;
    case 'ma_kh':
      p.request('ma_kh_request', '', ['ma_kh', 'ngay_ct', 'ma_nt']);

      break;
    default:
      break;
  }
}
function dir$s14HiddenColumnByTran(p){
  var gd = p.valForm('ma_gd');
	if(gd == 'KC') {
		p.setDisabled(['ma_so_thue','ten_kh','ten_kh2','dia_chi','nguoi_lh'], true);
		p.setInvisible('ma_kh', false);

		if(p.options.action == "NEW") {
			p.valForm('ma_kh', "" , true);
			p.valForm('ten_kh', "" , true);
			p.valForm('ten_kh2', "" , true);
			p.valForm('ma_so_thue', "" , true);
			p.valForm('dia_chi', "" , true);
			p.valForm('nguoi_lh', "" , true);
			p.valForm('dien_thoai', "" , true);
		}
		else {
			p.setDisabled('ma_gd', true);
		}
	}
	else {
		p.setInvisible('ma_kh', true);
		p.setDisabled(['ma_so_thue','ten_kh','ten_kh2','dia_chi','nguoi_lh'], false);

		if(p.options.action == "NEW") {
			p.valForm('ma_kh', "" , true);
			p.valForm('ten_kh', "" , true);
			p.valForm('ten_kh2', "" , true);
			p.valForm('ma_so_thue', "" , true);
			p.valForm('dia_chi', "" , true);
			p.valForm('nguoi_lh', "" , true);
			p.valForm('dien_thoai', "" , true);

		}
		else {
			p.setDisabled('ma_gd', true);
		}
	}
}

function getTax(o) {
  var p = document._dir;
  var tax = p.valForm('ma_so_thue').trim();
  var magd = p.valForm('ma_gd').trim();


  if (magd == 'KC') {
    $.showToast('Vui lòng chọn mã khách hàng.');
    return;
  }

  if (tax.length != 10 && tax.length != 13) {
    $.showToast('Thông tin mã số thuế không đúng.');
    return;
  }

  $.invoke('GetTax', { taxCode: tax }, this, 30000
    , function (result) {
      if (result) {
        var obj = JSON.parse(result);
        p.valForm('ten_kh', obj.Name, true);
        p.valForm('dia_chi', obj.Address, true);
		p.valForm('ten_kh2', obj.Other, true);
		p.valForm('nguoi_lh', obj.Contact, true);
		p.valForm('dien_thoai', obj.Telephone, true);

      }
    }, function (event) {} );
}






